ALTER TABLE users ADD COLUMN IF NOT EXISTS position text NOT NULL DEFAULT 'viewer';
UPDATE users SET position=CASE role::text WHEN 'admin' THEN 'ceo' WHEN 'accountant' THEN 'finance_officer' WHEN 'caseworker' THEN 'liaison' ELSE 'viewer' END WHERE position='viewer';
ALTER TABLE users ADD CONSTRAINT users_position_check CHECK(position IN ('ceo','supervision_deputy','finance_deputy','finance_officer','health_officer','education_officer','liaison','viewer'));
CREATE TABLE IF NOT EXISTS organization_units(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),code text UNIQUE NOT NULL,name text NOT NULL,unit_type text NOT NULL CHECK(unit_type IN ('executive','supervision','finance','health','education')),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now());
INSERT INTO organization_units(code,name,unit_type) VALUES('executive','مدیریت عامل','executive'),('supervision','معاونت سرپرستی','supervision'),('finance','معاونت مالی','finance'),('health','بهداشت و درمان','health'),('education','آموزش و تحصیل','education') ON CONFLICT(code) DO NOTHING;
ALTER TABLE users ADD COLUMN IF NOT EXISTS organization_unit_id uuid REFERENCES organization_units(id) ON DELETE SET NULL;
CREATE TABLE IF NOT EXISTS supervisors(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,national_id text,phone text NOT NULL DEFAULT '',notes text NOT NULL DEFAULT '',liaison_id uuid NOT NULL REFERENCES users(id),active boolean NOT NULL DEFAULT true,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(national_id IS NULL OR national_id ~ '^\d{10}$'));
CREATE INDEX IF NOT EXISTS supervisors_liaison_idx ON supervisors(liaison_id) WHERE active;
CREATE TABLE IF NOT EXISTS family_supervisor_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,supervisor_id uuid NOT NULL REFERENCES supervisors(id),starts_at timestamptz NOT NULL DEFAULT now(),ends_at timestamptz,assigned_by uuid REFERENCES users(id),reason text NOT NULL DEFAULT '',created_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS family_one_active_supervisor_idx ON family_supervisor_assignments(family_id) WHERE ends_at IS NULL;
CREATE INDEX IF NOT EXISTS family_supervisor_active_idx ON family_supervisor_assignments(supervisor_id,family_id) WHERE ends_at IS NULL;
CREATE TABLE IF NOT EXISTS service_referrals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),family_id uuid NOT NULL REFERENCES families(id) ON DELETE CASCADE,domain text NOT NULL CHECK(domain IN ('health','education')),assigned_to uuid NOT NULL REFERENCES users(id),status text NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','done','cancelled')),reason text NOT NULL,created_by uuid REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz);
CREATE INDEX IF NOT EXISTS service_referrals_assignee_idx ON service_referrals(assigned_to,status,created_at DESC);
CREATE INDEX IF NOT EXISTS service_referrals_family_idx ON service_referrals(family_id,domain,status);
